package career.assistant.application;
import career.assistant.application.entity.ApplicationStatus; import career.assistant.application.service.ApplicationWorkflowService; import career.assistant.company.entity.Company; import career.assistant.company.repository.CompanyRepository; import career.assistant.document.service.*; import career.assistant.job.entity.Job; import career.assistant.job.repository.JobRepository; import career.assistant.scraper.config.JobSource; import org.apache.poi.xwpf.usermodel.XWPFDocument; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.mock.web.MockMultipartFile; import org.springframework.transaction.annotation.Transactional; import java.io.ByteArrayOutputStream; import java.nio.file.Files; import java.nio.file.Path; import java.time.OffsetDateTime; import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties="career.application.allowlisted-domains=boards.greenhouse.io,jobs.lever.co,apply.workable.com") @Transactional class ApplicationPackageDryRunE2ETest {@Autowired ResumeService resumes;@Autowired CoverLetterService letters;@Autowired ApplicationWorkflowService workflow;@Autowired CompanyRepository companies;@Autowired JobRepository jobs;
 @Test void highConfidencePackageMovesThroughReviewAndDryRunWithoutSubmission()throws Exception{Company c=new Company();c.setName("Example UAE Employer");c=companies.save(c);Job j=new Job();j.setTitle("Senior DevOps Engineer");j.setCompanyId(c.getId());j.setLocation("Dubai, UAE");j.setCountry("UAE");j.setCity("Dubai");j.setExperienceMin(4);j.setExperienceMax(8);j.setSource(JobSource.GREENHOUSE);j.setSourceJobId("e2e-high-confidence");j.setJobUrl("https://boards.greenhouse.io/example/jobs/12345");j.setPostedAt(OffsetDateTime.now());j.setDescription("Responsibilities and required qualifications: Senior DevOps Engineer with AWS, Kubernetes, Terraform, Docker, GitHub Actions, CI/CD, Linux, Helm, Grafana and Monitoring. Build reliable cloud platforms and automate infrastructure delivery.");j=jobs.save(j);resumes.upload(new MockMultipartFile("file","master.docx",CoverLetterService.DOCX,masterDocx()),true);
  var generated=workflow.generate(j.getId(),false);assertEquals(ApplicationStatus.PENDING_REVIEW,generated.status());assertNotNull(generated.resumeVersionId());assertNotNull(generated.coverLetterId());var resumeFile=resumes.download(generated.resumeVersionId());var letterFile=letters.download(generated.coverLetterId());assertTrue(resumeFile.content().length>0);assertTrue(letterFile.content().length>0);Files.createDirectories(Path.of("target/generated-documents"));Files.write(Path.of("target/generated-documents/e2e-resume.docx"),resumeFile.content());Files.write(Path.of("target/generated-documents/representative-cover-letter.docx"),letterFile.content());String letter=letters.get(generated.coverLetterId()).content();assertTrue(letter.split("\\s+").length>=250&&letter.split("\\s+").length<=350);assertTrue(letter.contains("Example UAE Employer"));assertTrue(letter.contains("Senior DevOps Engineer"));assertFalse(letter.contains("verified experience"));assertFalse(letter.contains("exactly as verified"));assertFalse(letter.contains("located in India"));assertFalse(letter.contains("90-day notice"));assertFalse(letter.contains("open to relocating"));var repeated=workflow.generate(j.getId(),false);assertEquals(generated.id(),repeated.id());assertNotEquals(generated.resumeVersionId(),repeated.resumeVersionId());assertNotEquals(generated.coverLetterId(),repeated.coverLetterId());assertEquals(ApplicationStatus.PENDING_REVIEW,repeated.status());var ready=workflow.review(generated.id(),true,"Reviewed documents");assertEquals(ApplicationStatus.READY_TO_APPLY,ready.status());var dry=workflow.run(generated.id());assertEquals(ApplicationStatus.READY_TO_APPLY,dry.status(),dry.reason()+" score="+dry.score()+" confidence="+dry.confidence());assertEquals("GREENHOUSE",dry.adapter());assertNull(dry.confirmationId());assertNull(dry.appliedAt());assertTrue(dry.reason().contains("no request was submitted"));}
 private byte[] masterDocx()throws Exception{try(var d=new XWPFDocument();var out=new ByteArrayOutputStream()){String[] lines={"Sahana Gowda","sahana@example.com | +971 50 123 4567 | linkedin.com/in/sahana","Location: Dubai, UAE","Professional Summary","Senior DevOps Engineer building reliable cloud platforms and automating infrastructure delivery.","Skills","AWS, Kubernetes, Terraform, Docker, GitHub Actions, CI/CD, Linux, Helm, Grafana, Monitoring","Experience","Senior DevOps Engineer | Example Employer | Jan 2020 - Present","Built reliable AWS and Kubernetes cloud platforms using Terraform, Docker, GitHub Actions, CI/CD, Linux, Helm, Grafana and Monitoring.","Reduced deployment time by 20%.","Improved delivery workflows through repeatable infrastructure automation and operational monitoring.","Supported production platform reliability with Linux, Helm, Grafana, and CI/CD practices.","Certifications","AWS Certified Solutions Architect"};for(String line:lines)d.createParagraph().createRun().setText(line);d.write(out);return out.toByteArray();}}
}
